  (* [comment removed for export] *)
  Definition W4F0 : list cell :=
    [C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 n); C8 (Z_to_bv 64 SS); C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 dcap);
     C8 (Z_to_bv 64 (DST + dcap)); C8 (Z_to_bv 64 AW4_M5); C8 (Z_to_bv 64 AW4_M7); C8 (Z_to_bv 64 (DST + dcap));
     C8 (Z_to_bv 64 SS); C8 (Z_to_bv 64 (DT + 4))].

  (* [comment removed for export] *)
  Definition W4M (mm : amem) (w88 w96 w104 w112 w120 w128 w224 w232 : word) (ws : list word) : Prop :=
    (exists buf, u8arr asegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap)
    /\ bytes_at asegs mm SS (map (Z_to_bv 8) src)
    /\ bytes_at asegs mm (DT + 4) cbs
    /\ stk asegs mm lo SPF
    /\ rw_cells asegs mm SPF W4F0
    /\ rw_cells asegs mm (SPF + 88) [C8 w88; C8 w96; C8 w104; C8 w112]
    /\ rw_cells asegs mm (SPF + 120) [C8 w120; C8 w128; C8 (Z_to_bv 64 2147450880)]
    /\ stk asegs mm (SPF + 144) (SPF + 224)
    /\ rw_cells asegs mm (SPF + 224) [C8 w224; C8 w232]
    /\ u64arr asegs mm (SPF + 240) ws /\ length ws = 19%nat
    /\ rw_cells asegs mm (SP + -104) FRS
    /\ mem_inv asegs mm /\ munch DW m0 mm /\ wmono asegs m0 mm.

  (* [comment removed for export] *)
  Lemma w4m_stk : forall mm w88 w96 w104 w112 w120 w128 w224 w232 ws,
